/// A parsed `server.properties` file together with the raw document it came from.
///
/// Loaded files keep unknown keys; saving writes every known key back with its comment.
#[derive(Debug, Clone)]
pub struct ServerPropertiesDocument {
    document: PropertiesDocument,
    typed: ServerProperties,
}

impl Default for ServerPropertiesDocument {
    fn default() -> Self {
        let typed = ServerProperties::default();
        let mut document = PropertiesDocument::default();
        typed.apply_to(&mut document);
        Self { document, typed }
    }
}

impl ServerPropertiesDocument {
    /// Load a file, returning `None` when it does not exist.
    pub fn load(path: impl AsRef<Path>) -> Result<Option<Self>, ConfigError> {
        let path = path.as_ref();
        let text = match std::fs::read_to_string(path) {
            Ok(text) => text,
            Err(error) if error.kind() == std::io::ErrorKind::NotFound => return Ok(None),
            Err(error) => return Err(ConfigError::io(path, error)),
        };
        let mut document = PropertiesDocument::parse(&text);
        let typed = ServerProperties::from_document(&document)?;
        // Fill in keys the file did not contain while keeping unknown keys.
        typed.apply_to(&mut document);
        Ok(Some(Self { document, typed }))
    }

    /// The typed model.
    pub fn typed(&self) -> &ServerProperties {
        &self.typed
    }

    /// The raw document, including unknown keys.
    pub fn document(&self) -> &PropertiesDocument {
        &self.document
    }

    /// Replace the typed model and mirror it into the raw document.
    pub fn set_typed(&mut self, typed: ServerProperties) {
        self.typed = typed;
        self.typed.apply_to(&mut self.document);
    }

    /// Override one key, rejecting keys that are not part of the vanilla schema.
    pub fn set(&mut self, key: &str, value: &str) -> Result<(), ConfigError> {
        if self.typed.get_key(key).is_none() {
            return Err(ConfigError::Override {
                path: format!("server.{key}"),
                message: "unknown server.properties key".to_string(),
            });
        }
        self.document.set(key, value);
        let typed = ServerProperties::from_document(&self.document)?;
        typed.apply_to(&mut self.document);
        self.typed = typed;
        Ok(())
    }

    /// Render the file with a vanilla-style header and a comment above every known key.
    pub fn to_string_with_comments(&self) -> String {
        self.document
            .to_string_with_comments(ServerProperties::KEY_TABLE)
    }

    /// Write the file, creating parent directories as needed.
    pub fn save(&self, path: impl AsRef<Path>) -> Result<(), ConfigError> {
        let path = path.as_ref();
        if let Some(parent) = path.parent()
            && !parent.as_os_str().is_empty()
        {
            std::fs::create_dir_all(parent).map_err(|error| ConfigError::io(parent, error))?;
        }
        std::fs::write(path, self.to_string_with_comments())
            .map_err(|error| ConfigError::io(path, error))
    }
}

/// Difficulty level, as written to `server.properties`.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Difficulty {
    /// Peaceful.
    Peaceful,
    /// Easy.
    Easy,
    /// Normal.
    Normal,
    /// Hard.
    Hard,
}

impl Difficulty {
    /// All values, in vanilla order.
    pub const ALL: [Self; 4] = [Self::Peaceful, Self::Easy, Self::Normal, Self::Hard];

    /// The lowercase name used in `server.properties`.
    pub const fn as_str(self) -> &'static str {
        match self {
            Self::Peaceful => "peaceful",
            Self::Easy => "easy",
            Self::Normal => "normal",
            Self::Hard => "hard",
        }
    }
}

impl PropertyValue for Difficulty {
    fn parse_property(raw: &str) -> Result<Self, String> {
        match raw.trim().to_ascii_lowercase().as_str() {
            "peaceful" => Ok(Self::Peaceful),
            "easy" => Ok(Self::Easy),
            "normal" => Ok(Self::Normal),
            "hard" => Ok(Self::Hard),
            other => Err(format!(
                "expected one of peaceful, easy, normal, hard, found `{other}`"
            )),
        }
    }

    fn render_property(&self) -> String {
        self.as_str().to_string()
    }
}

