/// Region file compression algorithm.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum RegionFileCompression {
    /// zlib deflate.
    Deflate,
    /// LZ4.
    Lz4,
    /// No compression.
    None,
}

impl RegionFileCompression {
    /// The lowercase name used in `server.properties`.
    pub const fn as_str(self) -> &'static str {
        match self {
            Self::Deflate => "deflate",
            Self::Lz4 => "lz4",
            Self::None => "none",
        }
    }
}

impl PropertyValue for RegionFileCompression {
    fn parse_property(raw: &str) -> Result<Self, String> {
        match raw.trim().to_ascii_lowercase().as_str() {
            "deflate" => Ok(Self::Deflate),
            "lz4" => Ok(Self::Lz4),
            "none" => Ok(Self::None),
            other => Err(format!(
                "expected one of deflate, lz4, none, found `{other}`"
            )),
        }
    }

    fn render_property(&self) -> String {
        self.as_str().to_string()
    }
}
